-- The two checklists published on 2026-10-13: getting back in touch after
-- a long gap (Connection) and a project stalled halfway (Motivation).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-13`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('getting-back-in-touch-after-too-long', 'Getting Back in Touch After Too Long', 'For the friend you have been meaning to message for a year and now feel awkward about. It helps you send something rather than nothing, say the quiet part about the gap, and leave the ball in a place where it can actually come back.', 'Connection', '["Send it today rather than drafting it perfectly — the gap grows while you word it.", "Name the silence in one line, then move on — unmentioned gaps make the whole message heavy.", "Skip the apology beyond a sentence — long sorries ask them to do the reassuring.", "Mention one specific thing you remember — specifics prove you did not send this to twelve people.", "Offer a concrete time, not a vague catch-up — a vague soon has never once scheduled itself.", "Accept a short reply as a good outcome — warmth often comes back smaller than you sent it.", "Let one unanswered message be the end of it — silence is information, not a verdict on you.", "Put a reminder in for three months — drift is a scheduling problem more than a feelings one."]'::jsonb, 'as needed', array['Loneliness', 'Relationships']::text[], 1, '2026-10-13T16:00:00+00:00'::timestamptz),
  ('when-a-project-stalls-halfway', 'When a Project Stalls Halfway', 'For the thing you were excited about two months ago and have not touched in three weeks. It helps you work out whether it stalled from boredom, overwhelm or a wrong turn, and pick the one small step that gets it moving again.', 'Motivation', '["Write where it actually stopped, not why — the stopping point is usually a specific task.", "Ask whether it is boring, too big, or wrong — the three need completely different fixes.", "Cut the next step down to twenty minutes — a stalled project restarts small or not at all.", "Do the ugly version of the next piece — rough and finished beats perfect and unstarted.", "Decide out loud whether you still want it — abandoning on purpose is not the same as failing.", "Put one working session in the calendar — intentions without a slot do not survive a week.", "Tell someone the next step and the date — a witness changes the odds more than willpower.", "Shrink the finish line if it has drifted — the original plan is allowed to be renegotiated."]'::jsonb, 'as needed', array['Motivation', 'Goals']::text[], 1, '2026-10-13T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
